import { expect, type Page, test } from '@playwright/test';

async function submit__Value__(page: Page, value: string) {
  await page.goto('/');
  await page.getByRole('textbox', { name: '__Field label__' }).fill(value);
  await page.getByRole('button', { name: '__Action__' }).click();
}

test.describe('__Route__', () => {
  test('__describes the user-visible journey through the api__', async ({ page }) => {
    const answered = page.waitForResponse((response) =>
      response.url().includes('/trpc/__router__.__procedure__'),
    );

    await submit__Value__(page, '__value__');

    expect((await answered).status()).toBe(200);
    await expect(page.getByRole('status')).toHaveText('__expected outcome__');
  });

  test('__describes the validation message for bad input__', async ({ page }) => {
    await submit__Value__(page, '__invalid value__');

    await expect(page.getByRole('alert')).toHaveText('__validation message__');
  });

  test('says so when the api fails', async ({ page }) => {
    await page.route('**/trpc/**', (route) =>
      route.fulfill({ status: 500, contentType: 'application/json', body: '{}' }),
    );

    await submit__Value__(page, '__value__');

    await expect(page.getByRole('alert')).toHaveText('__error message__');
  });
});
# __Feature__

- **Result:** __the result that ships it, such as the reference result, `apps/`__
- **Decision:** [ADR 0045](../../.agents/decisions/0045-prds-state-intent-and-link-their-specs.md)

## Intent

__Who the feature is for, what it lets them do, and why it exists. Copy this
file to docs/prd/<feature>.md. Every tracked Markdown file directly in
docs/prd/ is a PRD, and `pnpm check:docs` checks each one.__

## Behaviours

- **__One promise, as the user sees it.__** __What the user does and what they
  see. Write the E2E test first, then link it by its exact title. Use `- `
  items only, and keep code fences out of this section.__
  - Proved by [__exact test title__](../../apps/web/e2e/__feature__.spec.ts)
import { Button, TextField } from '@repo/ui';
import { useGreetingForm } from './useGreetingForm';

export interface GreetingFormProps {
  readonly onGreet: (name: string) => void;
}

export function GreetingForm({ onGreet }: GreetingFormProps) {
  const { register, handleSubmit, formState } = useGreetingForm();
  const handleGreet = handleSubmit(({ name }) => onGreet(name));

  return (
    <form className="greeting-form" onSubmit={handleGreet} noValidate>
      <TextField
        label="Name"
        autoComplete="off"
        error={formState.errors.name?.message}
        {...register('name')}
      />
      <Button type="submit">Greet</Button>
    </form>
  );
}
import type { GreetingState } from './useGreeting';

const STATUS_TEXT = { idle: '', loading: 'Loading…', error: '' } as const;

export function GreetingMessage({ greeting }: { readonly greeting: GreetingState }) {
  return (
    <>
      <output className="greeting-message">
        {greeting.status === 'success' ? greeting.message : STATUS_TEXT[greeting.status]}
      </output>
      {greeting.status === 'error' ? (
        <p role="alert" className="greeting-error">
          Could not load the greeting
        </p>
      ) : null}
    </>
  );
}
