write('api/src/features/todos/integrations.ts','''import { randomUUID } from 'node:crypto';
import type { Todo } from './domain.ts';

const todos = new Map<string, Todo>();

export function readTodos(): Todo[] {
  return [...todos.values()];
}

export function insertTodo(title: string): Todo {
  const todo = { id: randomUUID(), title, completed: false };
  todos.set(todo.id, todo);
  return todo;
}

export function readTodo(id: string): Todo | undefined {
  return todos.get(id);
}

export function saveTodo(todo: Todo): Todo {
  todos.set(todo.id, todo);
  return todo;
}

export function removeTodo(id: string): void {
  todos.delete(id);
}''')
write('api/src/features/todos/application.ts','''import { type Todo, toggleTodo } from './domain.ts';
import { insertTodo, readTodo, readTodos, removeTodo, saveTodo } from './integrations.ts';

export function listTodos(): Todo[] {
  return readTodos();
}

export function createTodo(request: { readonly title: string }): Todo {
  return insertTodo(request.title);
}

export function toggleCompleted(request: { readonly id: string }): Todo | undefined {
  const todo = readTodo(request.id);
  return todo ? saveTodo(toggleTodo(todo)) : undefined;
}

export function deleteTodo(request: { readonly id: string }): void {
  removeTodo(request.id);
}''')
